-- 0011 — Push reminders: device subscriptions, a send log for idempotency,
-- a DB-held VAPID key pair, and the daily 10:00 IST (Mon–Sat) cron that calls
-- the send-reminders Edge Function.
-- Spec: docs/superpowers/specs/2026-11-18-reminders-and-calendar-design.md
--
-- No secret ever leaves the database: the cron secret is generated here inside
-- Vault, and the VAPID pair is generated by the Edge Function and stored in
-- private.vapid_keys (schema not exposed by PostgREST).

create extension if not exists pg_cron;
create extension if not exists pg_net with schema extensions;

-- Devices that turned reminders on. Mom (authenticated) manages her own rows.
create table push_subscriptions (
  id            uuid primary key default gen_random_uuid(),
  endpoint      text not null unique,
  p256dh        text not null,
  auth          text not null,
  user_agent    text,
  created_at    timestamptz not null default now(),
  last_seen_at  timestamptz not null default now()
);
alter table push_subscriptions enable row level security;
create policy push_subscriptions_authenticated_all on push_subscriptions
  for all to authenticated using (true) with check (true);

-- One row per notification actually claimed for sending. ref = run date for
-- 'orders'/'weekly_plan', event id for 'event_lead'. Service role only.
create table notification_log (
  id       uuid primary key default gen_random_uuid(),
  kind     text not null check (kind in ('orders', 'weekly_plan', 'event_lead')),
  ref      text not null,
  sent_at  timestamptz not null default now(),
  unique (kind, ref)
);
alter table notification_log enable row level security;

create schema if not exists private;
revoke all on schema private from public, anon, authenticated;

create table private.vapid_keys (
  id           int primary key default 1 check (id = 1),
  public_key   text not null,   -- base64url raw key, the browser's applicationServerKey
  public_jwk   jsonb not null,
  private_jwk  jsonb not null,
  created_at   timestamptz not null default now()
);

create or replace function public.get_vapid_public_key()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select public_key from private.vapid_keys where id = 1;
$$;
revoke execute on function public.get_vapid_public_key() from public, anon;
grant execute on function public.get_vapid_public_key() to authenticated;

create or replace function public.reminders_get_vapid()
returns table (public_key text, public_jwk jsonb, private_jwk jsonb)
language sql
stable
security definer
set search_path = ''
as $$
  select public_key, public_jwk, private_jwk from private.vapid_keys where id = 1;
$$;
revoke execute on function public.reminders_get_vapid() from public, anon, authenticated;
grant execute on function public.reminders_get_vapid() to service_role;

-- First writer wins; a concurrent second caller gets the winner's public key.
create or replace function public.reminders_store_vapid(p_public_key text, p_public_jwk jsonb, p_private_jwk jsonb)
returns text
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into private.vapid_keys (id, public_key, public_jwk, private_jwk)
  values (1, p_public_key, p_public_jwk, p_private_jwk)
  on conflict (id) do nothing;
  return (select public_key from private.vapid_keys where id = 1);
end;
$$;
revoke execute on function public.reminders_store_vapid(text, jsonb, jsonb) from public, anon, authenticated;
grant execute on function public.reminders_store_vapid(text, jsonb, jsonb) to service_role;

select vault.create_secret(encode(extensions.gen_random_bytes(32), 'hex'), 'reminders_cron_secret',
                           'Shared secret between pg_cron and the send-reminders Edge Function')
where not exists (select 1 from vault.secrets where name = 'reminders_cron_secret');

create or replace function public.reminders_cron_secret()
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select decrypted_secret from vault.decrypted_secrets where name = 'reminders_cron_secret';
$$;
revoke execute on function public.reminders_cron_secret() from public, anon, authenticated;
grant execute on function public.reminders_cron_secret() to service_role;

-- 04:30 UTC = 10:00 IST, Monday–Saturday.
select cron.unschedule('send-reminders') where exists (select 1 from cron.job where jobname = 'send-reminders');
select cron.schedule(
  'send-reminders',
  '30 4 * * 1-6',
  $job$
  select net.http_post(
    url := 'https://dhcookulkkundlibivgg.supabase.co/functions/v1/send-reminders',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', (select decrypted_secret from vault.decrypted_secrets where name = 'reminders_cron_secret')
    ),
    body := '{"action":"run"}'::jsonb,
    timeout_milliseconds := 30000
  );
  $job$
);
